    private void autoSetOutputPath() {
        String projectDir = System.getProperty("user.dir");
        String outputBaseDir = projectDir + File.separator + Texts.get("core.defaultOutputName");

        File outDirFile = new File(outputBaseDir);
        if (!outDirFile.isDirectory() && !outDirFile.mkdirs() && !outDirFile.isDirectory()) {
            log.warn(Texts.msg("log.maincontroller.01", outputBaseDir));
        }

        refs.outputFolderField().setText(outputBaseDir);
    }

    /** 输入目录变更：作为导入源增量合并（F3）——已有项目保持不变，新文件按绝对路径去重后追加末尾 */
    void onInputFolderChanged() {
        String text = refs.inputFolderField().getText();
        if (text == null || text.trim().isEmpty()) {
            saveGuiState();
            return;
        }
        if (!new File(text).isDirectory()) {
            log.warn(Texts.msg("log.maincontroller.02", text));
            saveGuiState();
            return;
        }
        importFromFolder(text);
        saveGuiState();
    }

    /** 增量导入：统一入口（BC-1：改为递归扫描 + 自动建组） */
    private void importFromFolder(String dir) {
        importByPaths(List.of(dir), Texts.get("dir.label", "path", dir), false);
    }

    // ==================== 统一导入（拖拽 + 浏览共用入口） ====================

    /** 是否正在导入（导入在途标志由 {@link PortEvent.ImportStateChanged} 事件驱动） */
    boolean isImporting() {
        return importPending;
    }

    /**
     * 统一导入入口：来源只接受地址字段。
     * 拖拽路径（fromDrag=true）在盘符根目录时弹确认框（BC-8）；浏览路径不弹。
     *
     * <p>本方法只留"拦截 + 确认展示 + 日志产出"；规范化/去重/建组/累计的规则在
     * {@link com.mhtextractor.app.WorkspaceImportService}，会话生命周期/轮次/配额确认往返/
     * 撤销压栈（BC-5）经端口命令下沉到 {@code app.WorkspaceImportCoordinator}。</p>
     */
    void importByPaths(List<String> addresses, String sourceDesc, boolean fromDrag) {
        if (addresses == null || addresses.isEmpty()) {
            return;
        }
        if (isImporting()) {
            log.warn(Texts.msg("log.maincontroller.03"));
            return;
